using System.Reflection;
using System.Text.Json.Nodes;
using Wcs.Wms.Contracts;
using Xunit;

namespace Wcs.ContractCheck.Test;

/// <summary>
/// The WMS document is generated by watching the client: these tests hold it against what the code
/// declares by other means, so a mistake of the observation shows up as a disagreement.
/// </summary>
public sealed class WmsContractDocumentTest
{
    private static IEnumerable<JsonObject> Operations(JsonObject document) =>
        document["paths"]!.AsObject().SelectMany(p => p.Value!.AsObject().Select(o => o.Value!.AsObject()));

    [Fact]
    public void EveryMethodOfIWarehouseIsOneOperationAndEveryRouteIsUsed()
    {
        var document = RepositoryContracts.Read(WmsContractDocument.FileName);
        var operations = Operations(document).Select(o => o["operationId"]!.GetValue<string>() + "Async").ToList();

        Assert.Equal(typeof(IWarehouse).GetMethods().Select(m => m.Name).Order(), operations.Order());
        Assert.Equal(WmsContractDocument.AllRoutes().Count, document["paths"]!.AsObject().Count);
    }

    [Fact]
    public void A404IsNoneExactlyWhereTheContractReturnsANullableAnswer()
    {
        var nullability = new NullabilityInfoContext();
        var nullable = typeof(IWarehouse).GetMethods()
            .Where(m => m.ReturnType.IsGenericType &&
                        nullability.Create(m.ReturnParameter).GenericTypeArguments[0].ReadState == NullabilityState.Nullable)
            .Select(m => m.Name[..^"Async".Length])
            .Order();

        var none = Operations(RepositoryContracts.Read(WmsContractDocument.FileName))
            .Where(o => o["x-wcs-not-found"]!.GetValue<string>() == "none")
            .Select(o => o["operationId"]!.GetValue<string>())
            .Order();

        Assert.Equal(nullable, none);
    }

    [Fact]
    public void PascalCaseRequestsAreThePostsThatReadAnAnswerAndCamelCaseThoseThatDoNot()
    {
        foreach (var operation in Operations(RepositoryContracts.Read(WmsContractDocument.FileName)))
        {
            if (operation["x-wcs-request-casing"]?.GetValue<string>() is not { } casing) continue;
            var read = operation["x-wcs-answer-body"]!.GetValue<string>() == "read";
            Assert.True(casing == (read ? WmsContractDocument.PascalCase : WmsContractDocument.CamelCase),
                $"{operation["operationId"]}: {casing}, answer body {(read ? "read" : "ignored")}");
        }
    }

    [Fact]
    public void TheOperationsWithAnOperationIdAreTheOnesThatAnswer409()
    {
        foreach (var operation in Operations(RepositoryContracts.Read(WmsContractDocument.FileName)))
            Assert.Equal(operation["x-wcs-operation-id"]!.GetValue<bool>(), operation["responses"]!["409"] != null);
    }
}
